	/**
	 * Default Constructor
	 */
    public InsurerService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new InsurerEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(InsurerRepository.class) );
		this.validator		= applicationContext.getBean(InsurerValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Insurer
	 */
		public Insurer createInsurer( CreateInsurerCommand command ) {

		Insurer entity = new Insurer();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setInsurerId( command.getInsurerId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setDomicileCountry( command.getDomicileCountry() );
            entity.setNaicNumber( command.getNaicNumber() );
            entity.setWebsite( command.getWebsite() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Insurer {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateInsurerCommand
	 * @return		Insurer
	 */
	public Insurer updateInsurer( UpdateInsurerCommand command ) {

		Insurer entity = new Insurer();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setInsurerId( command.getInsurerId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setDomicileCountry( command.getDomicileCountry() );
            entity.setNaicNumber( command.getNaicNumber() );
            entity.setWebsite( command.getWebsite() );
            entity.setProducts( command.getProducts() );
            entity.setDistributionPartners( command.getDistributionPartners() );
            entity.setPolicies( command.getPolicies() );
            entity.setClaims( command.getClaims() );
            entity.setReinsuranceAgreements( command.getReinsuranceAgreements() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Insurer {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteInsurerCommand
	 */
	public void delete( DeleteInsurerCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getInsurerId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Insurer {0} ", id );

	}

	/**
	 * Method to retrieve the Insurer via InsurerFetchOneSummary
	 * @param 	summary InsurerFetchOneSummary
	 * @return 	InsurerFetchOneResponse
	 */
	public Insurer getInsurer( InsurerFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "InsurerFetchOneSummary arg cannot be null" );

		Insurer entity = null;
		UUID id = summary.getInsurerId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Insurer using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Insurers
	 *
	 * @return 	List<Insurer>
	 */
    public List<Insurer> getAllInsurer() {
		List<Insurer> list = projector.findAll( new FindAllInsurerQuery() );
		return list;
	}


